import base64,io,json,pathlib,tarfile
root=pathlib.Path('/home/zbs/rf-round7-live-window-20261019-attempt2/delivery');root.mkdir(exist_ok=False)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode('')),mode='r:gz') as tf:
 for m in tf.getmembers():
  if not (root/m.name).resolve().is_relative_to(root) or not m.isfile():raise RuntimeError('Unsafe artifact path')
 tf.extractall(root,filter='data')
print(json.dumps(dict(delivery=str(root),raw_execution_preserved=True,cluster_resources_changed=False)))
